CustomField.formula:
IF(OR(
   MOD( Year(  Effective_Date__c  ),400)=0,
   AND(
       MOD(Year( Effective_Date__c   ),4)=0,
       MOD(Year( Effective_Date__c   ),100)<>0
       )
     )
,"Yes", 
   IF(OR(
       MOD( Year( Effective_Date__c   )-1,400)=0,
       AND(
           MOD(Year( Effective_Date__c   )-1,4)=0,
           MOD(Year( Effective_Date__c   )-1,100)<>0
           )
         )
   ,"Yes", "No"
   )
)
